404: function pocketRect(side,lane){if(side===0){return lane===0?{x0:20,x1:250,y0:200,y1:385}:{x0:290,x1:520,y0:200,y1:385};}return lane===0?{x0:20,x1:250,y0:415,y1:600}:{x0:290,x1:520,y0:415,y1:600};}
405: function pocketOpen(side,lane){const foe=1-side;const t=G.towers.find(t=>t.side===foe&&t.kind==="prin"&&t.lane===lane);return t&&t.dead;}
406: function inPocket(side,x,y){for(let lane=0;lane<2;lane++){if(!pocketOpen(side,lane))continue;const r=pocketRect(side,lane);if(x>=r.x0&&x<=r.x1&&y>=r.y0&&y<=r.y1)return true;}return false;}
407: function legalDeploy(side,x,y){if(y>368&&y<432)return false;for(const t of G.towers){if(!t.dead){const dx=x-t.x,dy=y-t.y;if(dx*dx+dy*dy<60*60)return false;}}const ownHalf=side===G.view?(side===0?y>=400:y<400):(side===0?y>=400:y<400);if(ownHalf&&y>30&&y<770)return true;return inPocket(side,x,y);}
