378: function musStep(){if(!G||!G.active||G.over||G.paused||G.phase!=="fight"||muted)return;const a=ac();if(!a)return;try{const s=G._mus=(G._mus||0)+1;const b=MUS_BASS[s%16];if(b){const o=a.createOscillator(),g=a.createGain();o.type="triangle";o.frequency.value=b;g.gain.value=.045;g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.2);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.22);}if(s%2===0){const o=a.createOscillator(),g=a.createGain();o.type="square";o.frequency.value=6000;g.gain.value=.012;g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.04);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.05);}}catch(e){}}
