411: constructor(k,side,lvl,x,y,gearId){const d=UNIT_DB[k];this.k=k;this.side=side;this.lvl=lvl;const s=lvlScale(lvl);let gid=(gearId&&GEAR_DB[gearId])?gearId:null;if(!gid){const g=side===G.view?(player.units[k]&&player.units[k].g):(G.foe&&G.foe.gear&&G.foe.gear[k]);if(g&&GEAR_DB[g])gid=g;}this.gear=gid;const gr=gid?GEAR_DB[gid]:{};this.max=d.hp*s*(gr.hp||1);this.hp=this.max;this.dmg=d.dmg*s*(gr.dmg||1);this.rng=d.rng+(gr.rng||0);this.spd=d.spd*(gr.spd||1);this.proj=d.proj;this.role=d.role||"melee";this.healAmt=(d.heal||0)*s;this.atkDelay=1/(d.atkSpd||1);this.cool=.4;this.t=Math.random()*10;this.age=0;this.x=x;this.y=y;this.moved=0;this.chargeUsed=false;this.stabUsed=false;this.slowT=0;this.slowF=1;this.burnT=0;this.burnDps=0;this._bt=0;this.flash=0;this.atkA=0;this.hitT=0;this.wind=0;this.vx=0;this.vy=0;this.px=x;this.py=y;}
412: esp(){return this.spd*(this.slowT>0?this.slowF:1);}
413: foe(){let best=null,bs=1e9;for(const e of G.ents){if(e.side===this.side||e.hp<=0)continue;const dx=e.x-this.x,dy=e.y-this.y;const d2=dx*dx+dy*dy;if(d2>this.rng*this.rng)continue;const w=(e.role==="tank")?d2*.64:d2;if(w<bs){bs=w;best=e;}}return best;}
