const fs = require('fs');
(async()=>{
  const res = await fetch('http://127.0.0.1:9222/json/new?file:///home/runner/work/PEPAPEPT/PEPAPEPT/index.html', {method:'PUT'});
  const target = await res.json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
  let id=0; const pending=new Map();
  ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}else if(m.method==='Runtime.exceptionThrown'){console.log('EXCEPTION',JSON.stringify(m.params.exceptionDetails));}else if(m.method==='Runtime.consoleAPICalled'){console.log('CONSOLE',m.params.type,m.params.args.map(a=>a.value||a.description).join(' '));}};
  const cmd=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
  await cmd('Runtime.enable'); await cmd('Page.enable');
  await new Promise(r=>setTimeout(r,3000));
  let out=await cmd('Runtime.evaluate',{expression:'JSON.stringify({title:document.title,active:document.querySelector(".screen.active")?.id,deck:document.getElementById("deckWarn")?.innerText,start:document.getElementById("startBtn")?.disabled,units:document.querySelectorAll(".ucard").length})',returnByValue:true});
  console.log('BOOT',out.result.result.value);
  await cmd('Runtime.evaluate',{expression:'startAIGame()',returnByValue:true});
  await new Promise(r=>setTimeout(r,2500));
  out=await cmd('Runtime.evaluate',{expression:'JSON.stringify({active:document.querySelector(".screen.active")?.id,phase:G?.phase,count:document.getElementById("vscount")?.innerText,hand:document.getElementById("hand")?.children.length,canvas:[document.getElementById("cvs")?.width,document.getElementById("cvs")?.height]})',returnByValue:true});
  console.log('GAME',out.result.result.value);
  await cmd('Runtime.evaluate',{expression:'quitToMenu(true)',returnByValue:true});
  await new Promise(r=>setTimeout(r,500));
  out=await cmd('Runtime.evaluate',{expression:'document.querySelector(".screen.active")?.id',returnByValue:true});
  console.log('MENU',out.result.result.value);
  ws.close();
})();

